const STORE_KEY = "habits";
const DONE_KEY = "doneByDate";

const els = {
  form: app.querySelector('[data-role="add-form"]'),
  nameInput: app.querySelector('[data-role="name-input"]'),
  addBtn: app.querySelector('[data-role="add-btn"]'),
  formError: app.querySelector('[data-role="form-error"]'),
  list: app.querySelector('[data-role="habit-list"]'),
  emptyHint: app.querySelector('[data-role="empty-hint"]'),
  doneCount: app.querySelector('[data-role="done-count"]'),
  totalCount: app.querySelector('[data-role="total-count"]'),
  rateValue: app.querySelector('[data-role="rate-value"]'),
  progressBar: app.querySelector('[data-role="progress-bar"]'),
  todayLabel: app.querySelector('[data-role="today-label"]'),
  backdrop: app.querySelector('[data-role="dialog-backdrop"]'),
  dialogTitle: app.querySelector('[data-role="dialog-title"]'),
  dialogText: app.querySelector('[data-role="dialog-text"]'),
  dialogCancel: app.querySelector('[data-role="dialog-cancel"]'),
  dialogConfirm: app.querySelector('[data-role="dialog-confirm"]')
};

let state = {};
let pendingDeleteId = null;

function pad2(n) {
  return n < 10 ? "0" + n : String(n);
}

function todayKey() {
  const d = new Date();
  return d.getFullYear() + "-" + pad2(d.getMonth() + 1) + "-" + pad2(d.getDate());
}

function todayLabelText() {
  const d = new Date();
  const week = ["周日", "周一", "周二", "周三", "周四", "周五", "周六"][d.getDay()];
  return "今天：" + d.getFullYear() + " 年 " + (d.getMonth() + 1) + " 月 " + d.getDate() + " 日 " + week;
}

function makeId() {
  return "h_" + Date.now().toString(36) + "_" + Math.random().toString(36).slice(2, 8);
}

function normalizeHabit(raw) {
  const item = raw && typeof raw === "object" ? raw : {};
  const habit = Object.assign({}, item);
  habit.id = typeof item.id === "string" && item.id ? item.id : makeId();
  habit.name = typeof item.name === "string" ? item.name : "";
  habit.createdAt = typeof item.createdAt === "string" ? item.createdAt : new Date().toISOString();
  if (!Array.isArray(habit.doneDates)) {
    habit.doneDates = [];
  } else {
    habit.doneDates = habit.doneDates.filter(function (d) { return typeof d === "string"; });
  }
  return habit;
}

function normalizeState(raw) {
  const src = raw && typeof raw === "object" ? raw : {};
  const next = Object.assign({}, src);
  const list = Array.isArray(src[STORE_KEY]) ? src[STORE_KEY] : [];
  next[STORE_KEY] = list.map(normalizeHabit);
  if (!next[DONE_KEY] || typeof next[DONE_KEY] !== "object" || Array.isArray(next[DONE_KEY])) {
    next[DONE_KEY] = {};
  }
  return next;
}

function isDoneToday(habit) {
  return habit.doneDates.indexOf(todayKey()) !== -1;
}

function showError(message) {
  els.formError.textContent = message;
  els.formError.hidden = false;
}

function clearError() {
  els.formError.textContent = "";
  els.formError.hidden = true;
}

function render() {
  const habits = state[STORE_KEY];
  const key = todayKey();
  let done = 0;

  els.list.textContent = "";
  habits.forEach(function (habit) {
    const finished = habit.doneDates.indexOf(key) !== -1;
    if (finished) {
      done += 1;
    }

    const li = document.createElement("li");
    li.className = "habit-item" + (finished ? " is-done" : "");
    li.dataset.habitId = habit.id;

    const main = document.createElement("div");
    main.className = "habit-main";

    const name = document.createElement("span");
    name.className = "habit-name";
    name.textContent = habit.name;

    const meta = document.createElement("span");
    meta.className = "habit-meta";
    meta.textContent = finished
      ? "今天已完成 · 累计打卡 " + habit.doneDates.length + " 天"
      : "今天未完成 · 累计打卡 " + habit.doneDates.length + " 天";

    main.appendChild(name);
    main.appendChild(meta);

    const actions = document.createElement("div");
    actions.className = "habit-actions";

    const toggle = document.createElement("button");
    toggle.type = "button";
    toggle.className = "btn btn-toggle";
    toggle.dataset.action = "toggle";
    toggle.dataset.habitId = habit.id;
    toggle.textContent = finished ? "取消打卡" : "完成打卡";

    const del = document.createElement("button");
    del.type = "button";
    del.className = "btn btn-delete";
    del.dataset.action = "delete";
    del.dataset.habitId = habit.id;
    del.textContent = "删除";

    actions.appendChild(toggle);
    actions.appendChild(del);

    li.appendChild(main);
    li.appendChild(actions);
    els.list.appendChild(li);
  });

  const total = habits.length;
  const rate = total === 0 ? 0 : Math.round((done / total) * 100);

  els.doneCount.textContent = String(done);
  els.totalCount.textContent = String(total);
  els.rateValue.textContent = rate + "%";
  els.progressBar.style.width = rate + "%";
  els.todayLabel.textContent = todayLabelText();
  els.emptyHint.hidden = total !== 0;
}

async function persist(nextState, errorMessage) {
  try {
    await appStore.setState(nextState);
    state = nextState;
    clearError();
    render();
    return true;
  } catch (err) {
    showError(errorMessage || "保存失败，请重试。");
    return false;
  }
}

async function addHabit(name) {
  const trimmed = name.trim();
  if (!trimmed) {
    showError("请输入习惯名称。");
    els.nameInput.focus();
    return;
  }

  const habit = normalizeHabit({ id: makeId(), name: trimmed, createdAt: new Date().toISOString(), doneDates: [] });
  const next = Object.assign({}, state);
  next[STORE_KEY] = state[STORE_KEY].concat([habit]);

  const ok = await persist(next, "添加失败，习惯未保存，请重试。");
  if (ok) {
    els.nameInput.value = "";
    els.nameInput.focus();
  }
}

async function toggleHabit(id) {
  const key = todayKey();
  const next = Object.assign({}, state);
  next[STORE_KEY] = state[STORE_KEY].map(function (habit) {
    if (habit.id !== id) {
      return habit;
    }
    const copy = Object.assign({}, habit);
    const dates = habit.doneDates.slice();
    const idx = dates.indexOf(key);
    if (idx === -1) {
      dates.push(key);
    } else {
      dates.splice(idx, 1);
    }
    copy.doneDates = dates;
    return copy;
  });

  await persist(next, "打卡状态保存失败，请重试。");
}

function openDeleteDialog(habit) {
  pendingDeleteId = habit.id;
  els.dialogTitle.textContent = "确认删除";
  els.dialogText.textContent = "确定要删除习惯「" + habit.name + "」吗？该习惯的打卡记录也会一并删除，此操作不可撤销。";
  els.backdrop.hidden = false;
  els.dialogConfirm.focus();
}

function closeDeleteDialog() {
  pendingDeleteId = null;
  els.backdrop.hidden = true;
}

async function confirmDelete() {
  const id = pendingDeleteId;
  closeDeleteDialog();
  if (!id) {
    return;
  }

  const next = Object.assign({}, state);
  next[STORE_KEY] = state[STORE_KEY].filter(function (habit) {
    return habit.id !== id;
  });

  await persist(next, "删除失败，请重试。");
}

async function init() {
  const raw = await appStore.getState();
  state = normalizeState(raw);
  render();

  els.form.addEventListener("submit", function (event) {
    event.preventDefault();
    addHabit(els.nameInput.value);
  });

  els.nameInput.addEventListener("input", function () {
    if (!els.formError.hidden) {
      clearError();
    }
  });

  els.list.addEventListener("click", function (event) {
    const btn = event.target.closest("button[data-action]");
    if (!btn) {
      return;
    }
    const id = btn.dataset.habitId;
    const habit = state[STORE_KEY].find(function (item) { return item.id === id; });
    if (!habit) {
      return;
    }
    if (btn.dataset.action === "toggle") {
      toggleHabit(id);
    } else if (btn.dataset.action === "delete") {
      openDeleteDialog(habit);
    }
  });

  els.dialogCancel.addEventListener("click", function () {
    closeDeleteDialog();
  });

  els.dialogConfirm.addEventListener("click", function () {
    confirmDelete();
  });

  els.backdrop.addEventListener("click", function (event) {
    if (event.target === els.backdrop) {
      closeDeleteDialog();
    }
  });

  document.addEventListener("keydown", function (event) {
    if (event.key === "Escape" && !els.backdrop.hidden) {
      closeDeleteDialog();
    }
  });
}

await init();

