:root {
  --bg: #0f172a;
  --bg-soft: #16213c;
  --panel: #1b2745;
  --panel-border: #2c3a5e;
  --text: #eef2ff;
  --text-muted: #a3b0d0;
  --accent: #4ade80;
  --accent-strong: #22c55e;
  --accent-soft: rgba(74, 222, 128, 0.16);
  --danger: #f87171;
  --danger-soft: rgba(248, 113, 113, 0.16);
  --shadow: 0 12px 30px rgba(4, 10, 26, 0.45);
  --radius: 14px;
}

#app {
  min-height: 100vh;
  background: radial-gradient(circle at 12% 0%, #1d2b52 0%, var(--bg) 55%, #0a1020 100%);
  color: var(--text);
  font-family: "Segoe UI", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  padding: 28px 18px 48px;
  box-sizing: border-box;
}

#app * {
  box-sizing: border-box;
}

.app-shell {
  max-width: 720px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.app-header {
  text-align: center;
  padding: 8px 0 4px;
}

.app-title {
  margin: 0;
  font-size: 30px;
  letter-spacing: 2px;
  color: var(--text);
}

.app-subtitle {
  margin: 8px 0 0;
  font-size: 14px;
  color: var(--text-muted);
}

.panel {
  background: var(--panel);
  border: 1px solid var(--panel-border);
  border-radius: var(--radius);
  padding: 18px;
  box-shadow: var(--shadow);
}

.panel-title {
  margin: 0 0 14px;
  font-size: 16px;
  font-weight: 600;
  color: var(--text);
  border-left: 4px solid var(--accent);
  padding-left: 10px;
  line-height: 1.2;
}

.add-form {
  display: flex;
  gap: 12px;
  align-items: flex-end;
  flex-wrap: wrap;
}

.field {
  flex: 1 1 220px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field-label {
  font-size: 13px;
  color: var(--text-muted);
}

.field-input {
  width: 100%;
  padding: 11px 13px;
  border-radius: 10px;
  border: 1px solid var(--panel-border);
  background: var(--bg-soft);
  color: var(--text);
  font-size: 15px;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.field-input::placeholder {
  color: #7c8ab0;
}

.field-input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}

.btn {
  border: 1px solid transparent;
  border-radius: 10px;
  padding: 11px 18px;
  font-size: 15px;
  cursor: pointer;
  font-family: inherit;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease, transform 0.1s ease;
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background: var(--accent-strong);
  color: #06210f;
  font-weight: 600;
}

.btn-primary:hover {
  background: var(--accent);
}

.btn-ghost {
  background: transparent;
  border-color: var(--panel-border);
  color: var(--text-muted);
}

.btn-ghost:hover {
  color: var(--text);
  border-color: var(--text-muted);
}

.btn-danger {
  background: var(--danger);
  color: #2b0707;
  font-weight: 600;
}

.btn-danger:hover {
  background: #fca5a5;
}

.form-error {
  margin: 12px 0 0;
  font-size: 13px;
  color: var(--danger);
  background: var(--danger-soft);
  border: 1px solid rgba(248, 113, 113, 0.35);
  border-radius: 10px;
  padding: 9px 12px;
}

.stats-row {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.stat {
  flex: 1 1 120px;
  background: var(--bg-soft);
  border: 1px solid var(--panel-border);
  border-radius: 12px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  align-items: center;
}

.stat-value {
  font-size: 24px;
  font-weight: 700;
  color: var(--accent);
}

.stat-label {
  font-size: 12px;
  color: var(--text-muted);
}

.progress-track {
  margin-top: 14px;
  height: 10px;
  border-radius: 999px;
  background: var(--bg-soft);
  border: 1px solid var(--panel-border);
  overflow: hidden;
}

.progress-bar {
  height: 100%;
  width: 0%;
  background: linear-gradient(90deg, var(--accent-strong), var(--accent));
  transition: width 0.25s ease;
}

.stats-date {
  margin: 10px 0 0;
  font-size: 12px;
  color: var(--text-muted);
  text-align: right;
}

.habit-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.habit-item {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--bg-soft);
  border: 1px solid var(--panel-border);
  border-radius: 12px;
  padding: 12px 14px;
}

.habit-item.is-done {
  border-color: rgba(74, 222, 128, 0.55);
  background: var(--accent-soft);
}

.habit-main {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.habit-name {
  font-size: 16px;
  color: var(--text);
  word-break: break-word;
}

.habit-item.is-done .habit-name {
  color: var(--accent);
}

.habit-meta {
  font-size: 12px;
  color: var(--text-muted);
}

.habit-actions {
  display: flex;
  gap: 8px;
  flex-shrink: 0;
}

.btn-toggle {
  background: transparent;
  border: 1px solid var(--accent);
  color: var(--accent);
  padding: 8px 14px;
  font-size: 14px;
}

.btn-toggle:hover {
  background: var(--accent-soft);
}

.habit-item.is-done .btn-toggle {
  background: var(--accent-strong);
  border-color: var(--accent-strong);
  color: #06210f;
  font-weight: 600;
}

.btn-delete {
  background: transparent;
  border: 1px solid rgba(248, 113, 113, 0.5);
  color: var(--danger);
  padding: 8px 12px;
  font-size: 14px;
}

.btn-delete:hover {
  background: var(--danger-soft);
}

.empty-hint {
  margin: 0;
  padding: 22px 12px;
  text-align: center;
  font-size: 14px;
  color: var(--text-muted);
  border: 1px dashed var(--panel-border);
  border-radius: 12px;
}

.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(6, 11, 24, 0.72);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 50;
}

.dialog-backdrop[hidden] {
  display: none;
}

.dialog {
  width: 100%;
  max-width: 380px;
  background: var(--panel);
  border: 1px solid var(--panel-border);
  border-radius: var(--radius);
  padding: 20px;
  box-shadow: var(--shadow);
}

.dialog-title {
  margin: 0 0 10px;
  font-size: 17px;
  color: var(--text);
}

.dialog-text {
  margin: 0 0 18px;
  font-size: 14px;
  color: var(--text-muted);
  line-height: 1.6;
  word-break: break-word;
}

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

@media (max-width: 480px) {
  .add-form {
    flex-direction: column;
    align-items: stretch;
  }

  .habit-item {
    flex-direction: column;
    align-items: stretch;
  }

  .habit-actions {
    justify-content: flex-end;
  }
}
